def is_prime(n):
    # Check if n is less than or equal to 1
    if n <= 1:
        return False

    # Check if n is 2 or an even number
    if n == 2 or n % 2 == 0:
        return True

    # Check if n is divisible by any number from 3 to sqrt(n)
    limit = int(math.sqrt(n)) + 1
    for i in range(3, limit):
        if n % i == 0:
            return False

    # If no factor is found, n is prime
    return True

